CREATE TABLE "nekoproxy_bindings" (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "node_id" BIGINT NOT NULL UNIQUE,
    "api_url" VARCHAR(512) NOT NULL,
    "forward_id" VARCHAR(128) NOT NULL,
    "session_id" VARCHAR(128) NOT NULL,
    "created_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "updated_at" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "nekoproxy_bindings_api_url_forward_id" UNIQUE ("api_url", "forward_id"),
    CONSTRAINT "nekoproxy_bindings_node_fk" FOREIGN KEY ("node_id") REFERENCES "nodes" ("id") ON DELETE CASCADE
);
